def test_spawn(name, js_code):
    print(f'\n---> Testing Spawn with: {name}')
    force_stop()
    adb('logcat', '-c')
    dev = get_device()
    script = None
    session = None
    try:
        pid = dev.spawn([TARGET_PKG])
        session = dev.attach(pid)
        script = session.create_script(js_code)
        script.load()
        dev.resume(pid)
        adb('shell', 'am', 'start', '-n', f'{TARGET_PKG}/{MAIN_ACT}')
        for i in range(5):
            time.sleep(1)
            cpid = get_pid()
            if not cpid:
                print(f'FAILED on {name} at second {i + 1}!')
                log = adb('logcat', '-d')
                for line in log.stdout.splitlines():
                    if 'Abort message' in line or 'JNI ERROR' in line:
                        print('  CRASH:', line)
                return False
        print(f'PASSED {name}! (PID {get_pid()})')
        return True
    except Exception as e:
        print(f'EXCEPTION on {name}: {e}')
        return False
    finally:
        if script:
            try:
                script.unload()
            except:
                pass
        if session:
            try:
                session.detach()
            except:
                pass
        force_stop()

